 * 
 * Input: mat = [[1,1,1,1,1,1]]
 * Output: 21
 * 
 * Example 4:
 * 
 * Input: mat = [[1,0,1],[0,1,0],[1,0,1]]
 * Output: 5
 * 
 * Constraints:
 * 
 * 	1 <= rows <= 150
 * 	1 <= columns <= 150
 * 	0 <= mat[i][j] <= 1
 ******************************************************************************************************/
// Bruce
class Solution {
public:
    int numSubmat(vector<vector<int>>& mat) {

        int m = mat.size();
        int n = mat[0].size();
        int count = 0;
        for(int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
              count += helper(mat, i, j);

            }
        }
        return count;
    }

private:
    int helper(vector<vector<int>>& mat,int a, int b) {
        int m = mat.size();
        int n = mat[0].size();
        int count = 0;
        for(int i = a; i < m; i++) {
            for(int j = b; j < n; j++) {
                if(mat[i][j])
                    ++count;
                else
                    n = j;
            }
        }
        return count;
    }
};

