 * Total number of rectangles = 8 + 5 + 2 + 4 + 2 + 2 + 1 = 24.
 * 
 * Example 3:
 * 
 * Input: mat = [[1,1,1,1,1,1]]
 * Output: 21
 * 
 * Example 4:
 * 
 * Input: mat = [[1,0,1],[0,1,0],[1,0,1]]
 * Output: 5
 * 
 * Constraints:
 * 
 * 	1 <= rows <= 150
 * 	1 <= columns <= 150
 * 	0 <= mat[i][j] <= 1
 ******************************************************************************************************/
class Solution {
    public int numSubmat(int[][] mat) {
    int res = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            for (int m = 1; m <= mat.length; m++) {
                for (int n = 1; n <= mat[0].length; n++) {
                    if (good(mat, m, n, i, j))
                        res++;
                    else 
                        break;
                    }
                }   
            }
        }
        return res;
    }
    public boolean good(int[][] mat, int m, int n, int x, int y) { 
        if (m + x > mat.length || n + y > mat[0].length)
            return false;  
        for (int i = x; i < x + m; i++)
            for (int j = y; j < y + n; j++)
                if (mat[i][j] == 0)
                    return false;
        return true;
    }

}
